Fixes: 90942f9fac05 ("perf: Use current->flags & PF_KTHREAD|PF_USER_WORKER instead of current->mm == NULL")
Closes: https://lore.kernel.org/all/0d877e6f-41a7-4724-875d-0b0a27b8a545@roeck-us.net/
Reported-by: Guenter Roeck <linux@roeck-us.net>
Signed-off-by: Steven Rostedt (Google) <rostedt@goodmis.org>
Signed-off-by: Peter Zijlstra (Intel) <peterz@infradead.org>
Tested-by: Guenter Roeck <linux@roeck-us.net>
Cc: stable@vger.kernel.org
Link: https://patch.msgid.link/20260129102821.46484722@gandalf.local.home

Here is the root cause:
The bug occurs because the condition !(current->flags & (PF_KTHREAD | PF_USER_WORKER)) is used to determine if a task is a user task, but during task exit, the mm field is set to NULL while the flags remain unchanged, causing a NULL pointer dereference when perf attempts to access user space memory. The correct check requires also verifying that current->mm is not NULL.

Here is the patch:

 static void perf_sample_regs_user(struct perf_regs *regs_user,
 				  struct pt_regs *regs)
 {
 	if (user_mode(regs)) {
 		regs_user->abi = perf_reg_abi(current);
 		regs_user->regs = regs;
-	} else if (!(current->flags & (PF_KTHREAD | PF_USER_WORKER))) {
+	} else if (is_user_task(current)) {
 		perf_get_regs_user(regs_user, regs);
 	} else {
 		regs_user->abi = PERF_SAMPLE_REGS_ABI_NONE;
 		regs_user->regs = NULL;
 	}
 }


 static u64 perf_virt_to_phys(u64 virt)
 {
 	u64 phys_addr = 0;

 	if (!virt)
 		return 0;

 	if (virt >= TASK_SIZE) {
 		/* If it's vmalloc()d memory, leave phys_addr as 0 */
 		if (virt_addr_valid((void *)(uintptr_t)virt) &&
 		    !(virt >= VMALLOC_START && virt < VMALLOC_END))
 			phys_addr = (u64)virt_to_phys((void *)(uintptr_t)virt);
 	} else {
 		/*
 		 * Walking the pages tables for user address.
 		 * Interrupts are disabled, so it prevents any tear down
 		 * of the page tables.
 		 * Try IRQ-safe get_user_page_fast_only first.
 		 * If failed, leave phys_addr as 0.
 		 */
-		if (!(current->flags & (PF_KTHREAD | PF_USER_WORKER))) {
+		if (is_user_task(current)) {
 			struct page *p;

 			pagefault_disable();
 			if (get_user_page_fast_only(virt, 0, &p)) {
 				phys_addr = page_to_phys(p) + virt % PAGE_SIZE;
 				put_page(p);
 			}
 			pagefault_enable();
 		}
 	}

 	return phys_addr;
 }


 struct perf_callchain_entry *
 perf_callchain(struct perf_event *event, struct pt_regs *regs)
 {
 	bool kernel = !event->attr.exclude_callchain_kernel;
 	bool user   = !event->attr.exclude_callchain_user &&
-		!(current->flags & (PF_KTHREAD | PF_USER_WORKER));
+		is_user_task(current);
 	/* Disallow cross-task user callchains. */
 	bool crosstask = event->ctx->task && event->ctx->task != current;
 	bool defer_user = IS_ENABLED(CONFIG_UNWIND_USER) && user &&
 			  event->attr.defer_callchain;
 	const u32 max_stack = event->attr.sample_max_stack;
 	struct perf_callchain_entry *callchain;
 	u64 defer_cookie;

 	if (!current->mm)
 		user = false;

 	if (!kernel && !user)
 		return &__empty_callchain;

 	if (!(user && defer_user && !crosstask &&
 	      unwind_deferred_request(&perf_unwind_work, &defer_cookie) >= 0))
 		defer_cookie = 0;

 	callchain = get_perf_callchain(regs, kernel, user, max_stack,
 				       crosstask, true, defer_cookie);

 	return callchain ?: &__empty_callchain;
 }



